#!/usr/bin/env sh
# Senzu Theme for fzf: Senzu Dusk
# Generated by senzu
#
# Source this file in your shell rc to apply (zsh/bash):
#
#   [ -f ~/.config/fzf/senzu-dusk.sh ] && . ~/.config/fzf/senzu-dusk.sh
#
# It appends the Senzu --color spec to FZF_DEFAULT_OPTS, preserving any other
# fzf options you set. To switch variants, source a different senzu fzf file
# instead (fzf merges --color flags, last one wins per element).

export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=fg:#d2cbec,bg:#16141b,hl:#fad07a,fg+:#d2cbec,bg+:#393449,hl+:#fad07a,info:#5f9ecf,border:#2d283b,prompt:#8197bf,pointer:#d0c5ed,marker:#99ad6a,spinner:#c6b6ee,header:#5d596a,gutter:#393449,preview-fg:#d2cbec,preview-bg:#16141b"
